{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-7egcl4/src/cursor.js","content":"/**
 * A position within one line of the document. Advancing past whitespace
 * also collapses an unquoted `#` or `;` to the end of the line, since a
 * comment marker outside a quoted string ends the line wherever it sits.
 */
export class Cursor {
  constructor(line) {
    this.line = line
    this.pos = 0
  }

  peek() {
    return this.pos < this.line.length ? this.line[this.pos] : undefined
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  skip() {
    while (this.pos < this.line.length && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
    if (this.pos < this.line.length && (this.line[this.pos] === '#' || this.line[this.pos] === ';')) {
      this.pos = this.line.length
    }
  }
}
"}

