{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-7egcl4/src/path.js","content":"/**
 * A path is a list of segments from the document root: plain strings for
 * object keys, and `{ index }` objects for array positions. Joining follows
 * the `keys` command's format, which error messages reuse as well.
 */
export function joinPath(segments) {
  let out = ''
  for (const segment of segments) {
    if (typeof segment === 'object') {
      out += `[${segment.index}]`
    } else {
      out += out ? `.${segment}` : segment
    }
  }
  return out
}
"}

