  while (!cur.atEnd() && NAME_CHAR.test(cur.line[cur.pos])) cur.pos++
  if (cur.pos === start) throw new ConfError(lineNo, 'expected a name')
  return cur.line.slice(start, cur.pos)
}

function parseDottedName(cur, lineNo) {
  const names = [parseName(cur, lineNo)]
  while (true) {
    const save = cur.pos
    cur.skip()
    if (cur.peek() === '.') {
      cur.pos++
      cur.skip()
      names.push(parseName(cur, lineNo))
    } else {
      cur.pos = save
      break
    }
  }
  return names
}

function parseBasicString(cur, lineNo) {
  cur.pos++ // opening quote
  let result = ''
  while (true) {
    if (cur.atEnd()) throw new ConfError(lineNo, 'unterminated string')
    const c = cur.line[cur.pos]
    if (c === '"') {
      cur.pos++
      return result
    }
    if (c === '\\') {
      cur.pos++
      if (cur.atEnd()) throw new ConfError(lineNo, 'unterminated string')
      const e = cur.line[cur.pos]
      cur.pos++
      switch (e) {
        case '"':
          result += '"'
          break
        case '\\':
          result += '\\'
          break
        case 'n':
          result += '\n'
          break
        case 't':
          result += '\t'
          break
        case 'r':
          result += '\r'
          break
        case '0':
          result += '\0'
          break
        case 'u': {
          const hex = cur.line.slice(cur.pos, cur.pos + 4)
          if (hex.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
            throw new ConfError(lineNo, 'invalid escape \\u')
          }
          result += String.fromCharCode(parseInt(hex, 16))
          cur.pos += 4
          break
        }
        default:
          throw new ConfError(lineNo, `invalid escape \\${e}`)
      }
    } else {
      result += c
      cur.pos++
    }
  }
}

function parseLiteralString(cur, lineNo) {
  cur.pos++ // opening quote
  const start = cur.pos
  while (true) {
    if (cur.atEnd()) throw new ConfError(lineNo, 'unterminated string')
    if (cur.line[cur.pos] === "'") {
      const result = cur.line.slice(start, cur.pos)
      cur.pos++
      return result
    }
    cur.pos++
  }
}

const INTEGER_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function parseBareValue(cur, lineNo) {
  const start = cur.pos
  while (!cur.atEnd()) {
    const ch = cur.line[cur.pos]
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
    cur.pos++
  }
  const token = cur.line.slice(start, cur.pos)
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INTEGER_RE.test(token)) return { kind: 'integer', value: Number(token.replace(/_/g, '')) }
  if (FLOAT_RE.test(token) && /[.eE]/.test(token)) {
    return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  }
  throw new ConfError(lineNo, `invalid value ${token}`)
}

function parseValue(cur, pathSegs, lineNo) {
  cur.skip()
  const c = cur.peek()
  if (c === undefined || c === ',' || c === ']' || c === '}') {
    throw new ConfError(lineNo, 'expected a value')
  }
  if (c === '"') return { kind: 'string', value: parseBasicString(cur, lineNo) }
  if (c === "'") return { kind: 'string', value: parseLiteralString(cur, lineNo) }
  if (c === '[') return parseArrayValue(cur, pathSegs, lineNo)
  if (c === '{') return parseInlineTableValue(cur, pathSegs, lineNo)
  return parseBareValue(cur, lineNo)
}

function parseArrayValue(cur, pathSegs, lineNo) {
  cur.pos++ // '['
  const items = []
  cur.skip()
  if (cur.peek() === ']') {
    cur.pos++
    return { kind: 'array', items }
  }
  let idx = 0
  while (true) {
    items.push(parseValue(cur, pathSegs.concat({ index: idx }), lineNo))
    idx++
    cur.skip()
    const c = cur.peek()
    if (c === ',') {
      cur.pos++
      cur.skip()
      if (cur.peek() === ']') {
        cur.pos++
        return { kind: 'array', items }
      }
      continue
    }
    if (c === ']') {
      cur.pos++
      return { kind: 'array', items }
    }
    throw new ConfError(lineNo, 'unterminated array')
  }
}

/**
 * Walks all but the last of `names` as tables under `startTable`, creating
 * intermediate tables as needed and descending into the last element of an
 * array of tables. Returns the container table for the final name and the
 * path segments leading to it.
 */
function resolveIntermediate(startTable, names, startPathSegs, lineNo) {
  let table = startTable
  const pathSegs = startPathSegs.slice()
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    pathSegs.push(name)
    const existing = table.data[name]
    if (existing === undefined) {
      const t = newTable(false)
      table.data[name] = t
      table = t
    } else if (existing.kind === 'table') {
      table = existing
    } else if (existing.kind === 'aot') {
      table = existing.items[existing.items.length - 1]
    } else {
      throw new ConfError(lineNo, `${joinPath(pathSegs)} is not a table`)
    }
  }
  return { table, pathSegs }
}

function assignKey(container, names, containerPathSegs, value, lineNo) {
  const { table: parent, pathSegs } = resolveIntermediate(container, names, containerPathSegs, lineNo)
  const lastName = names[names.length - 1]
  const fullSegs = pathSegs.concat(lastName)
  if (parent.data[lastName] !== undefined) {
    throw new ConfError(lineNo, `key ${joinPath(fullSegs)} is defined twice`)
  }
  parent.data[lastName] = value
}

function parseInlineTableValue(cur, pathSegs, lineNo) {
  cur.pos++ // '{'
  cur.skip()
  const table = newTable(false)
  if (cur.peek() === '}') {
    cur.pos++
    return table
  }
  while (true) {
    const names = parseDottedName(cur, lineNo)
    cur.skip()
    if (cur.peek() !== '=') throw new ConfError(lineNo, 'expected = in an inline table')
    cur.pos++
    const { table: parent, pathSegs: interSegs } = resolveIntermediate(table, names, pathSegs, lineNo)
    const lastName = names[names.length - 1]
    const fullSegs = interSegs.concat(lastName)
    const value = parseValue(cur, fullSegs, lineNo)
    if (parent.data[lastName] !== undefined) {
      throw new ConfError(lineNo, `key ${joinPath(fullSegs)} is defined twice`)
    }
    parent.data[lastName] = value
    cur.skip()
    const c = cur.peek()
    if (c === ',') {
      cur.pos++
      cur.skip()
      continue
    }
    if (c === '}') {
      cur.pos++
      return table
    }
    throw new ConfError(lineNo, 'unterminated inline table')
  }
}

function parseHeaderLine(cur, lineNo, root) {
  cur.pos++ // '['
  let isArray = false
  if (cur.peek() === '[') {
    isArray = true
    cur.pos++
  }
  cur.skip()
  const names = parseDottedName(cur, lineNo)
  cur.skip()
  if (cur.peek() !== ']') throw new ConfError(lineNo, 'unterminated table header')
  cur.pos++
  if (isArray) {
    if (cur.peek() !== ']') throw new ConfError(lineNo, 'unterminated table header')
    cur.pos++
  }
  cur.skip()
  if (!cur.atEnd()) throw new ConfError(lineNo, 'trailing text after a table header')

  const { table: parent, pathSegs } = resolveIntermediate(root, names, [], lineNo)
  const lastName = names[names.length - 1]
  const fullSegs = pathSegs.concat(lastName)
  const fullPath = joinPath(fullSegs)
  const existing = parent.data[lastName]

  if (isArray) {
    if (existing === undefined) {
      const t = newTable(false)
      parent.data[lastName] = { kind: 'aot', items: [t] }
      return { table: t, pathSegs: fullSegs }
    }
    if (existing.kind === 'aot') {
      const t = newTable(false)
      existing.items.push(t)
      return { table: t, pathSegs: fullSegs }
    }
    throw new ConfError(lineNo, `${fullPath} is not an array of tables`)
  }

  if (existing === undefined) {
    const t = newTable(true)
    parent.data[lastName] = t
    return { table: t, pathSegs: fullSegs }
  }
  if (existing.kind === 'table') {
    if (existing.declaredByHeader) throw new ConfError(lineNo, `table ${fullPath} is defined twice`)
    existing.declaredByHeader = true
    return { table: existing, pathSegs: fullSegs }
  }
  throw new ConfError(lineNo, `${fullPath} is not a table`)
}

function parseKeyValueLine(cur, lineNo, currentTable, currentPathSegs) {
  const names = parseDottedName(cur, lineNo)
  cur.skip()
  if (cur.peek() !== '=') throw new ConfError(lineNo, 'expected key = value')
  cur.pos++
  const { pathSegs: interSegs } = resolveIntermediate(currentTable, names, currentPathSegs, lineNo)
  const fullSegs = interSegs.concat(names[names.length - 1])
  const value = parseValue(cur, fullSegs, lineNo)
  cur.skip()
  if (!cur.atEnd()) throw new ConfError(lineNo, 'trailing text after a value')
  assignKey(currentTable, names, currentPathSegs, value, lineNo)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable(true)
  let currentTable = root
  let currentPathSegs = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const cur = new Cursor(lines[i])
    cur.skip()
    if (cur.atEnd()) continue

    if (cur.peek() === '[') {
      const result = parseHeaderLine(cur, lineNo, root)
      currentTable = result.table
      currentPathSegs = result.pathSegs
    } else {
      parseKeyValueLine(cur, lineNo, currentTable, currentPathSegs)
    }
  }

  return root
}
"}

