 * Renders a parsed document tree (see parser.js) as either canonical JSON
 * or the `keys` listing.
 */
function sortedKeys(data) {
  return Object.keys(data).sort()
}

function toJSONValue(node) {
  switch (node.kind) {
    case 'table': {
      const obj = {}
      for (const key of sortedKeys(node.data)) obj[key] = toJSONValue(node.data[key])
      return obj
    }
    case 'aot':
      return node.items.map(toJSONValue)
    case 'array':
      return node.items.map(toJSONValue)
    default:
      return node.value
  }
}

export function buildJSONText(root) {
  return `${JSON.stringify(toJSONValue(root), null, 2)}\n`
}

function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'aot':
    case 'array':
      return 'array'
    default:
      return node.kind
  }
}

function walkKeys(node, path, out) {
  out.push(`${path} ${typeName(node)}`)
  if (node.kind === 'table') {
    for (const key of sortedKeys(node.data)) {
      walkKeys(node.data[key], path ? `${path}.${key}` : key, out)
    }
  } else if (node.kind === 'aot' || node.kind === 'array') {
    node.items.forEach((item, i) => walkKeys(item, `${path}[${i}]`, out))
  }
}

export function buildKeysText(root) {
  const out = []
  for (const key of sortedKeys(root.data)) walkKeys(root.data[key], key, out)
  return out.map((line) => `${line}\n`).join('')
}
"}

