const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function parseBareValue(cur, lineNo) {
  // A `#` that abuts a bare value with no whitespace before it is part of
  // that value's text, but a `;` always starts a comment: only `#` is kept
  // as part of the token here.
  const start = cur.pos
  while (!cur.atEnd()) {
    const ch = cur.line[cur.pos]
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}' || ch === ';') break
    cur.pos++
  }
  const token = cur.line.slice(start, cur.pos)

